# Generated by curate-skills
# Workflow: corvallis_weather_precip_gapfill
# Function: plot_weather_comparison

import os
import re
import tempfile
from datetime import date

import matplotlib

matplotlib.use("Agg")
import matplotlib.dates as mdates  # noqa: E402
import matplotlib.pyplot as plt  # noqa: E402
import pandas as pd  # noqa: E402

PANEL_ORDER = ["PRCP", "TMAX", "TMIN"]
PANEL_TITLES = {
    "PRCP": "Precipitation (PRCP)",
    "TMAX": "Maximum temperature (TMAX)",
    "TMIN": "Minimum temperature (TMIN)",
}
Y_LABELS = {
    "PRCP": "Precipitation (mm)",
    "TMAX": "Temperature (°C)",
    "TMIN": "Temperature (°C)",
}
REQUIRED_COLS = ["variable", "month_day", "this_year_value", "ten_year_avg"]


def _axis_date(month_day):
    """Map an 'MM-DD' season day onto a leap-year axis (Dec 2023 .. Mar 2024) so Feb 29 fits."""
    month, day = int(month_day[:2]), int(month_day[3:])
    year = 2023 if month == 12 else 2024
    return date(year, month, day)


def plot_weather_comparison(folder: str, input1: str, output1: str) -> None:
    tmpdir = tempfile.mkdtemp()

    # Fan-in: discover every per-rank result file produced upstream.
    prefix_part, _, suffix_part = input1.partition("{rank}")
    pattern = re.compile(r"^" + re.escape(prefix_part) + r"\d+" + re.escape(suffix_part) + r"$")
    keys = faasr_get_folder_list(prefix=folder)
    names = sorted({k.rsplit("/", 1)[-1] for k in keys if pattern.match(k.rsplit("/", 1)[-1])})
    faasr_log(f"Found {len(names)} result files matching {input1}: {names}")
    if not names:
        msg = f"ERROR: no files matching {input1} found in {folder}"
        faasr_log(msg)
        raise RuntimeError(msg)

    data = {}
    for i, name in enumerate(names):
        local = os.path.join(tmpdir, f"in_{i}.csv")
        faasr_get_file(local_file=local, remote_folder=folder, remote_file=name)
        if not os.path.exists(local) or os.path.getsize(local) == 0:
            msg = f"ERROR: input {name} is missing or empty"
            faasr_log(msg)
            raise RuntimeError(msg)
        df = pd.read_csv(local, dtype={"month_day": str, "variable": str})
        missing = [c for c in REQUIRED_COLS if c not in df.columns]
        if missing:
            msg = f"ERROR: {name} lacks columns {missing}"
            faasr_log(msg)
            raise RuntimeError(msg)
        variables = df["variable"].dropna().unique()
        if len(variables) != 1:
            msg = f"ERROR: {name} should hold exactly one variable, found {list(variables)}"
            faasr_log(msg)
            raise RuntimeError(msg)
        var = str(variables[0]).strip()
        if var in data:
            msg = f"ERROR: variable {var} appears in more than one result file"
            faasr_log(msg)
            raise RuntimeError(msg)
        df["axis_date"] = pd.to_datetime([_axis_date(md) for md in df["month_day"]])
        df["this_year_value"] = pd.to_numeric(df["this_year_value"], errors="coerce")
        df["ten_year_avg"] = pd.to_numeric(df["ten_year_avg"], errors="coerce")
        data[var] = df.sort_values("axis_date")
        faasr_log(f"Loaded {var} from {name}: {len(df)} rows")

    absent = [v for v in PANEL_ORDER if v not in data]
    if absent:
        msg = f"ERROR: missing results for variables {absent}"
        faasr_log(msg)
        raise RuntimeError(msg)

    fig, axes = plt.subplots(3, 1, figsize=(11, 10), sharex=True)
    for ax, var in zip(axes, PANEL_ORDER):
        df = data[var]
        # 2025 line: only season days that are real 2025 dates inside the window
        # (skips the non-existent 2025-02-29 so Feb 28 connects to Mar 01).
        if "this_year_date" in df.columns:
            this_df = df[df["this_year_date"].notna() & (df["this_year_date"].astype(str).str.strip() != "")]
        else:
            this_df = df
        ax.plot(this_df["axis_date"], this_df["this_year_value"], linestyle="-", color="tab:blue",
                linewidth=1.5, label="2025")
        ax.plot(df["axis_date"], df["ten_year_avg"], linestyle="--", color="tab:gray",
                linewidth=1.5, label="2015-2024 average")
        ax.set_title(PANEL_TITLES[var])
        ax.set_ylabel(Y_LABELS[var])
        ax.grid(True, alpha=0.3)
        ax.legend(loc="upper right")

    axes[-1].set_xlim(pd.Timestamp(_axis_date("12-02")), pd.Timestamp(_axis_date("03-31")))
    axes[-1].xaxis.set_major_locator(mdates.DayLocator(bymonthday=[1, 15]))
    axes[-1].xaxis.set_major_formatter(mdates.DateFormatter("%b %d"))
    axes[-1].set_xlabel("Date (Dec 02 - Mar 31)")
    plt.setp(axes[-1].get_xticklabels(), rotation=45, ha="right")
    fig.suptitle("Winter weather in Corvallis, Oregon (station USC00351862): "
                 "2025 vs 2015-2024 average")
    fig.tight_layout(rect=(0, 0, 1, 0.97))

    local_out = os.path.join(tmpdir, "figure.png")
    fig.savefig(local_out, format="png", dpi=150)
    plt.close(fig)

    faasr_put_file(local_file=local_out, remote_folder=folder, remote_file=output1)
    faasr_log(f"Uploaded {output1}")
